package com.staging.sg.fraud.gateway.service;
import com.staging.sg.fraud.gateway.crypto.FraudKeyExchangeHsm;import org.jpos.iso.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;
@Component public class PermanentIsoKeyClientProcessor{private final FraudKeyExchangeHsm hsm;private final String member,zmk,keyDelivery,keyAck;private final int envelopeField,kcvField;
 public PermanentIsoKeyClientProcessor(FraudKeyExchangeHsm hsm,@Value("${fraud-gateway.iso.member-id:}")String member,@Value("${fraud-gateway.iso.zmk-reference:}")String zmk,@Value("${fraud-gateway.iso.key-delivery-code:161}")String delivery,@Value("${fraud-gateway.iso.key-ack-code:162}")String ack,@Value("${fraud-gateway.iso.key-envelope-field:96}")int envelope,@Value("${fraud-gateway.iso.key-kcv-field:48}")int kcv){this.hsm=hsm;this.member=member;this.zmk=zmk;this.keyDelivery=delivery;this.keyAck=ack;this.envelopeField=envelope;this.kcvField=kcv;}
 public boolean isTakDelivery(ISOMsg message){return message.hasField(70)&&keyDelivery.equals(message.getString(70));}
 public ISOMsg importAndAcknowledge(ISOMsg delivery)throws Exception{if(member.isBlank()||zmk.isBlank())throw new IllegalStateException("Member and HSM ZMK reference are required");String encrypted=envelopeField==96?ISOUtil.hexString(delivery.getBytes(envelopeField)):delivery.getString(envelopeField);String kcv=delivery.getString(kcvField);hsm.importTakUnderZmk(member,zmk,encrypted,kcv);ISOMsg ack=new ISOMsg();ack.setPackager(delivery.getPackager());ack.setMTI("0800");if(delivery.hasField(7))ack.set(7,delivery.getString(7));if(delivery.hasField(11))ack.set(11,delivery.getString(11));ack.set(70,keyAck);return ack;}
}
